import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { execFileSync } from "node:child_process";
import { afterEach, describe, expect, it } from "vitest";

const roots = new Set<string>();

function createTempHome(): string {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "pi-messenger-cli-install-"));
  roots.add(home);
  return home;
}

afterEach(() => {
  for (const root of roots) {
    fs.rmSync(root, { recursive: true, force: true });
  }
  roots.clear();
});

describe("install.mjs", () => {
  it("refuses to create a legacy extension copy when native package install is configured", () => {
    const home = createTempHome();
    const settingsPath = path.join(home, ".pi", "agent", "settings.json");
    fs.mkdirSync(path.dirname(settingsPath), { recursive: true });
    fs.writeFileSync(settingsPath, JSON.stringify({ packages: ["npm:pi-messenger"] }));

    let output = "";
    try {
      execFileSync(process.execPath, ["install.mjs"], {
        cwd: process.cwd(),
        env: { ...process.env, HOME: home },
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "pipe"],
      });
    } catch (error) {
      output = String((error as { stdout?: string }).stdout ?? "");
    }

    expect(output).toContain("already installed via pi's native package flow");
    expect(fs.existsSync(path.join(home, ".pi", "agent", "extensions", "pi-messenger"))).toBe(false);
  });
});

import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import * as store from "../../crew/store.ts";
import { executeTaskAction } from "../../crew/task-actions.ts";
import { createTempCrewDirs } from "../helpers/temp-dirs.ts";

function writeCrewDependenciesConfig(cwd: string, dependencies: "advisory" | "strict"): void {
  const configPath = path.join(cwd, ".pi", "messenger", "crew", "config.json");
  fs.mkdirSync(path.dirname(configPath), { recursive: true });
  fs.writeFileSync(configPath, JSON.stringify({ dependencies }, null, 2));
}

describe("crew/task-actions", () => {
  it("starts a todo task and assigns it", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Implement auth", "Desc");

    const result = executeTaskAction(cwd, "start", task.id, "AgentA");

    expect(result.success).toBe(true);
    expect(result.task?.status).toBe("in_progress");
    expect(result.task?.assigned_to).toBe("AgentA");
  });

  it("returns success when agent is already assigned to in_progress task", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Implement auth", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "start", task.id, "AgentA");

    expect(result.success).toBe(true);
    expect(result.task?.status).toBe("in_progress");
    expect(result.task?.assigned_to).toBe("AgentA");
  });

  it("rejects start when task is in_progress but assigned to different agent", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Implement auth", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "start", task.id, "AgentB");

    expect(result.success).toBe(false);
    expect(result.error).toBe("invalid_status");
  });

  it("rejects starting when dependencies are not done", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    writeCrewDependenciesConfig(cwd, "strict");
    const dep = store.createTask(cwd, "Dependency", "Desc");
    const task = store.createTask(cwd, "Main", "Desc", [dep.id]);

    const result = executeTaskAction(cwd, "start", task.id, "AgentA");

    expect(result.success).toBe(false);
    expect(result.error).toBe("unmet_dependencies");
    expect(result.unmetDependencies).toEqual([dep.id]);
  });

  it("allows starting when dependencies are not done in advisory mode", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    writeCrewDependenciesConfig(cwd, "advisory");
    const dep = store.createTask(cwd, "Dependency", "Desc");
    const task = store.createTask(cwd, "Main", "Desc", [dep.id]);

    const result = executeTaskAction(cwd, "start", task.id, "AgentA");

    expect(result.success).toBe(true);
    expect(result.task?.status).toBe("in_progress");
    expect(result.error).toBeUndefined();
  });

  it("rejects starting milestones", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Milestone", "Desc");
    store.updateTask(cwd, task.id, { milestone: true });

    const result = executeTaskAction(cwd, "start", task.id, "AgentA");

    expect(result.success).toBe(false);
    expect(result.error).toBe("milestone_not_startable");
  });

  it("blocks and unblocks an in-progress task", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const blocked = executeTaskAction(cwd, "block", task.id, "AgentA", "Waiting on API");
    expect(blocked.success).toBe(true);
    expect(store.getTask(cwd, task.id)?.status).toBe("blocked");

    const unblocked = executeTaskAction(cwd, "unblock", task.id, "AgentA");
    expect(unblocked.success).toBe(true);
    expect(store.getTask(cwd, task.id)?.status).toBe("todo");
  });

  it("prevents deleting active in-progress worker tasks", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "delete", task.id, "AgentA", undefined, {
      isWorkerActive: () => true,
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe("active_worker");
    expect(store.getTask(cwd, task.id)).not.toBeNull();
  });

  it("prevents resetting active worker tasks", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "reset", task.id, "AgentA", undefined, {
      isWorkerActive: () => true,
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe("active_worker");
    expect(store.getTask(cwd, task.id)?.status).toBe("in_progress");
  });

  it("prevents cascade-reset when a dependent has an active worker", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const parent = store.createTask(cwd, "Parent", "Desc");
    const child = store.createTask(cwd, "Child", "Desc", [parent.id]);
    store.startTask(cwd, child.id, "AgentA");

    const result = executeTaskAction(cwd, "cascade-reset", parent.id, "AgentA", undefined, {
      isWorkerActive: taskId => taskId === child.id,
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe("active_worker");
    expect(store.getTask(cwd, child.id)?.status).toBe("in_progress");
  });

  it("deletes non-active tasks", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");

    const result = executeTaskAction(cwd, "delete", task.id, "AgentA", undefined, {
      isWorkerActive: () => false,
    });

    expect(result.success).toBe(true);
    expect(store.getTask(cwd, task.id)).toBeNull();
  });

  it("stops an in-progress task with an active worker", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "stop", task.id, "AgentA", undefined, {
      isWorkerActive: () => true,
    });

    expect(result.success).toBe(true);
    const updated = store.getTask(cwd, task.id);
    expect(updated?.status).toBe("todo");
    expect(updated?.assigned_to).toBeUndefined();
    const progress = store.getTaskProgress(cwd, task.id);
    expect(progress).toContain("Worker stopped by user");
  });

  it("rejects stop when task is not in_progress", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");

    const result = executeTaskAction(cwd, "stop", task.id, "AgentA", undefined, {
      isWorkerActive: () => true,
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe("invalid_status");
  });

  it("stop without active worker resets task to todo", () => {
    const { cwd } = createTempCrewDirs();
    store.createPlan(cwd, "docs/PRD.md");
    const task = store.createTask(cwd, "Task", "Desc");
    store.startTask(cwd, task.id, "AgentA");

    const result = executeTaskAction(cwd, "stop", task.id, "AgentA", undefined, {
      isWorkerActive: () => false,
    });

    expect(result.success).toBe(true);
    const updated = store.getTask(cwd, task.id);
    expect(updated?.status).toBe("todo");
    expect(updated?.assigned_to).toBeUndefined();
  });
});

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { runLegacyAgentCleanupMigration, uninstallAgents } from "../../../crew/utils/install.ts";

const roots = new Set<string>();

function createTempHome(): string {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "pi-messenger-install-test-"));
  roots.add(home);
  return home;
}

function writeFile(filePath: string): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, "agent");
}

afterEach(() => {
  for (const root of roots) {
    try {
      fs.rmSync(root, { recursive: true, force: true });
    } catch {}
  }
  roots.clear();
});

describe("crew/utils/install", () => {
  it("uninstallAgents removes legacy shared crew agent files", () => {
    const homeDir = createTempHome();
    const agentsDir = path.join(homeDir, ".pi", "agent", "agents");

    writeFile(path.join(agentsDir, "crew-worker.md"));
    writeFile(path.join(agentsDir, "crew-planner.md"));
    writeFile(path.join(agentsDir, "crew-repo-scout.md"));
    writeFile(path.join(agentsDir, "other-agent.md"));

    const result = uninstallAgents({ homeDir });

    expect(result.errors).toEqual([]);
    expect(result.removed.sort()).toEqual([
      "crew-planner.md",
      "crew-repo-scout.md",
      "crew-worker.md",
    ]);
    expect(fs.existsSync(path.join(agentsDir, "other-agent.md"))).toBe(true);
  });

  it("runLegacyAgentCleanupMigration runs once and uses marker file", () => {
    const homeDir = createTempHome();
    const agentsDir = path.join(homeDir, ".pi", "agent", "agents");
    const markerPath = path.join(homeDir, ".pi", "agent", "messenger", "migrations", "legacy-crew-agent-cleanup-v1.json");

    writeFile(path.join(agentsDir, "crew-worker.md"));

    const first = runLegacyAgentCleanupMigration({ homeDir });
    expect(first.ran).toBe(true);
    expect(first.removed).toContain("crew-worker.md");
    expect(fs.existsSync(markerPath)).toBe(true);

    writeFile(path.join(agentsDir, "crew-worker.md"));

    const second = runLegacyAgentCleanupMigration({ homeDir });
    expect(second.ran).toBe(false);
    expect(second.removed).toEqual([]);
    expect(fs.existsSync(path.join(agentsDir, "crew-worker.md"))).toBe(true);
  });
});

import { describe, expect, it, vi } from "vitest";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

vi.mock("@earendil-works/pi-tui", () => ({
  matchesKey: () => false,
  truncateToWidth: (value: string) => value,
  visibleWidth: (value: string) => value.length,
}));

function createMockPi() {
  return {
    on: vi.fn(),
    registerTool: vi.fn(),
    registerCommand: vi.fn(),
    registerMessageRenderer: vi.fn(),
    sendMessage: vi.fn(),
    appendEntry: vi.fn(),
  };
}

describe("agent message renderer", () => {
  it("renders persisted message and ts details without crashing", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-08-23T12:01:00.000Z"));
    try {
      const pi = createMockPi();
      const { default: piMessengerExtension } = await import("../index.ts");
      piMessengerExtension(pi as unknown as ExtensionAPI);

      const rendererFactory = pi.registerMessageRenderer.mock.calls.find(
        ([customType]) => customType === "agent_message",
      )?.[1];

      const renderer = rendererFactory(
        { details: { from: "\u001b[31mPeer\u001b[0m", to: "Self", message: "\u001b[32mHistorical body\u001b[0m", ts: "2026-08-23T12:00:00.000Z" } },
        {},
        { fg: (_color: string, text: string) => text },
      );

      expect(renderer.render(80)).toEqual([
        "From Peer (1m ago)",
        "",
        "Historical body",
      ]);
    } finally {
      vi.useRealTimers();
    }
  });
});

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { autonomousState, startAutonomous } from "../../crew/state.ts";
import { createTempCrewDirs } from "../helpers/temp-dirs.ts";

vi.mock("@earendil-works/pi-tui", () => ({
  matchesKey: () => false,
  truncateToWidth: (value: string) => value,
  visibleWidth: (value: string) => value.length,
}));

vi.mock("typebox", () => ({
  Type: {
    Unsafe: (schema: unknown) => schema,
    Optional: (schema: unknown) => schema,
    String: (schema: unknown) => schema,
    Number: (schema: unknown) => schema,
    Boolean: (schema: unknown) => schema,
    Any: (schema: unknown) => schema,
    Array: (schema: unknown) => schema,
    Object: (schema: unknown) => schema,
  },
}));

function createMockPi() {
  const handlers = new Map<string, Array<(event: unknown, ctx: any) => unknown>>();

  return {
    handlers,
    on: vi.fn((event: string, handler: (event: unknown, ctx: any) => unknown) => {
      const existing = handlers.get(event) ?? [];
      existing.push(handler);
      handlers.set(event, existing);
    }),
    registerTool: vi.fn(),
    registerCommand: vi.fn(),
    registerMessageRenderer: vi.fn(),
    sendMessage: vi.fn(),
    appendEntry: vi.fn(),
  };
}

function createEventContext(cwd: string) {
  return {
    cwd,
    hasUI: false,
    ui: {
      notify: vi.fn(),
      setStatus: vi.fn(),
      custom: vi.fn(),
      theme: { fg: (_color: string, text: string) => text },
    },
    sessionManager: {
      getEntries: () => [],
      getSessionId: () => "test-session",
    },
    model: { id: "test-model" },
  } as any;
}

function resetAutonomousState(): void {
  autonomousState.active = false;
  autonomousState.cwd = null;
  autonomousState.waveNumber = 0;
  autonomousState.waveHistory = [];
  autonomousState.startedAt = null;
  autonomousState.stoppedAt = null;
  autonomousState.stopReason = null;
  autonomousState.concurrency = 2;
  autonomousState.autoOverlayPending = false;
  autonomousState.pid = null;
}

describe("agent_end autonomous continuation guards", () => {
  const tempHomes: string[] = [];

  beforeEach(() => {
    resetAutonomousState();
    const home = fs.mkdtempSync(path.join(os.tmpdir(), "pi-messenger-home-"));
    tempHomes.push(home);
    vi.stubEnv("HOME", home);
    vi.stubEnv("PI_MESSENGER_DIR", path.join(home, ".pi", "agent", "messenger"));
  });

  afterEach(() => {
    vi.unstubAllEnvs();
    for (const home of tempHomes) {
      fs.rmSync(home, { force: true, recursive: true });
    }
    tempHomes.length = 0;
  });

  it("stops restored autonomous state when session is not registered", async () => {
    const { cwd } = createTempCrewDirs();
    const ctx = createEventContext(cwd);
    const pi = createMockPi();
    const { default: piMessengerExtension } = await import("../../index.ts");
    piMessengerExtension(pi as any);

    const agentEndHandler = pi.handlers.get("agent_end")?.[0];
    expect(agentEndHandler).toBeTruthy();

    startAutonomous(cwd, 2);
    expect(autonomousState.active).toBe(true);

    await agentEndHandler?.({}, ctx);

    expect(autonomousState.active).toBe(false);
    expect(autonomousState.stopReason).toBe("manual");
    expect(pi.appendEntry).toHaveBeenCalledWith("crew-state", autonomousState);
    expect(pi.sendMessage).not.toHaveBeenCalled();
  });

  it("skips autonomous continuation handling inside worker sessions", async () => {
    const { cwd } = createTempCrewDirs();
    const ctx = createEventContext(cwd);
    const pi = createMockPi();
    const { default: piMessengerExtension } = await import("../../index.ts");
    piMessengerExtension(pi as any);

    const agentEndHandler = pi.handlers.get("agent_end")?.[0];
    expect(agentEndHandler).toBeTruthy();

    startAutonomous(cwd, 2);
    vi.stubEnv("PI_CREW_WORKER", "1");

    await agentEndHandler?.({}, ctx);

    expect(autonomousState.active).toBe(true);
    expect(pi.appendEntry).not.toHaveBeenCalled();
    expect(pi.sendMessage).not.toHaveBeenCalled();
  });
});

import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import { createTempCrewDirs } from "../helpers/temp-dirs.ts";
import { discoverSubagentRoles } from "../../crew/team/subagent-roles.ts";
import * as teamStore from "../../crew/team/store.ts";

describe("team subagent role discovery", () => {
  it("merges builtin, user, project, and profile role metadata", () => {
    const { cwd } = createTempCrewDirs();
    const home = path.join(cwd, "home");
    const builtinDir = path.join(home, ".pi", "agent", "extensions", "subagent", "agents");
    const userDir = path.join(home, ".pi", "agent", "agents");
    const projectDir = path.join(cwd, ".pi", "agents");
    fs.mkdirSync(builtinDir, { recursive: true });
    fs.mkdirSync(userDir, { recursive: true });
    fs.mkdirSync(projectDir, { recursive: true });

    fs.writeFileSync(path.join(builtinDir, "worker.md"), `---\nname: worker\ndescription: Builtin worker\nmodel: builtin-model\nthinking: low\nskills: testing, api\n---\nBuiltin prompt.`);
    fs.writeFileSync(path.join(userDir, "worker.md"), `---\r\nname: worker\r\ndescription: User worker\r\nmodel: user-model\r\n---\r\nUser prompt.`);
    fs.writeFileSync(path.join(userDir, "simplifier.md"), `---\nname: simplifier\ndescription: User simplifier\n---\nSimplify project-specific work.`);
    fs.writeFileSync(path.join(userDir, "uppercase-scout.md"), `---\nname: Scout\ndescription: Uppercase scout\n---\nScout prompt.`);
    fs.writeFileSync(path.join(userDir, "bad.md"), `---\nname: __proto__\ndescription: Bad role\n---\nBad prompt.`);
    fs.writeFileSync(path.join(userDir, "bad-object-key.md"), `---\nname: toString\ndescription: Bad object key\n---\nBad prompt.`);
    fs.writeFileSync(path.join(projectDir, "worker.md"), `---\nname: worker\ndescription: Project worker\n---\nProject prompt.`);

    const discovered = discoverSubagentRoles(cwd, { homeDir: home });
    expect(discovered.worker.description).toBe("Project worker");
    expect(discovered.worker.model).toBe("user-model");
    expect(discovered.worker.skills).toEqual(["testing", "api"]);
    expect(discovered.worker.prompt).toContain("Project prompt");
    expect(discovered.simplifier.description).toBe("User simplifier");
    expect(discovered.scout.description).toBe("Uppercase scout");
    expect(Object.hasOwn(discovered, "__proto__")).toBe(false);
    expect(Object.hasOwn(discovered, "toString")).toBe(false);

    teamStore.saveProfile({ name: "profile", roles: { worker: { model: "profile-model" } } }, home);
    teamStore.setActiveTeam(cwd, "profile", "profile");
    const roles = teamStore.resolveRoles(cwd, { homeDir: home });
    expect(roles.worker.description).toBe("Project worker");
    expect(roles.worker.model).toBe("profile-model");
  });
});

import * as fs from "node:fs";
import * as path from "node:path";
import { EventEmitter } from "node:events";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { resolveModel, pushModelArgs, spawnAgents } from "../../crew/agents.ts";
import { createTempCrewDirs, type TempCrewDirs } from "../helpers/temp-dirs.ts";

const spawnMock = vi.hoisted(() => vi.fn());

vi.mock("node:child_process", () => ({
  spawn: spawnMock,
}));

type MockProcess = EventEmitter & {
  stdout: EventEmitter;
  stderr: EventEmitter;
  killed: boolean;
  exitCode: number | null;
  kill: ReturnType<typeof vi.fn>;
};

function createMockProcess(exitCode: number): MockProcess {
  const proc = new EventEmitter() as MockProcess;
  proc.stdout = new EventEmitter();
  proc.stderr = new EventEmitter();
  proc.killed = false;
  proc.exitCode = null;
  proc.kill = vi.fn(() => true);

  queueMicrotask(() => {
    proc.exitCode = exitCode;
    proc.emit("exit", exitCode);
    proc.emit("close", exitCode);
  });

  return proc;
}

function writeWorkerAgent(cwd: string, model?: string, tools?: string[]): void {
  const modelLine = model ? `model: ${model}\n` : "";
  const toolsLine = tools ? `tools: ${tools.join(", ")}\n` : "";
  const content = `---
name: crew-worker
description: Test worker
crewRole: worker
${modelLine}${toolsLine}---
You are a test worker.
`;

  const filePath = path.join(cwd, ".pi", "messenger", "crew", "agents", "crew-worker.md");
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
}

function writeCrewConfig(cwd: string, models: Record<string, string | null>): void {
  const configPath = path.join(cwd, ".pi", "messenger", "crew", "config.json");
  fs.mkdirSync(path.dirname(configPath), { recursive: true });
  fs.writeFileSync(configPath, JSON.stringify({ models }));
}

describe("crew/model override", () => {
  let dirs: TempCrewDirs;

  beforeEach(() => {
    dirs = createTempCrewDirs();
    spawnMock.mockReset();
    spawnMock.mockImplementation(() => createMockProcess(0));
  });

  it("resolveModel follows task -> params -> role -> config -> session -> agent priority", () => {
    expect(resolveModel("task-model", "param-model", "role-model", "config-model", "session-model", "agent-model")).toBe("task-model");
    expect(resolveModel(undefined, "param-model", "role-model", "config-model", "session-model", "agent-model")).toBe("param-model");
    expect(resolveModel(undefined, undefined, "role-model", "config-model", "session-model", "agent-model")).toBe("role-model");
    expect(resolveModel(undefined, undefined, undefined, "config-model", "session-model", "agent-model")).toBe("config-model");
    expect(resolveModel(undefined, undefined, undefined, undefined, "session-model", "agent-model")).toBe("session-model");
    expect(resolveModel(undefined, undefined, undefined, undefined, undefined, "agent-model")).toBe("agent-model");
  });

  it("resolveModel returns undefined when all inputs are undefined", () => {
    expect(resolveModel(undefined, undefined, undefined, undefined)).toBeUndefined();
  });

  it("spawnAgents passes resolved model override in spawn args", async () => {
    writeWorkerAgent(dirs.cwd, "agent-default-model");

    await spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
      modelOverride: "wave-override-model",
    }], dirs.cwd);

    expect(spawnMock).toHaveBeenCalledTimes(1);
    const args = spawnMock.mock.calls[0][1] as string[];
    const modelFlagIndex = args.indexOf("--model");

    expect(modelFlagIndex).toBeGreaterThan(-1);
    expect(args[modelFlagIndex + 1]).toBe("wave-override-model");
  });

  it("spawnAgents falls back to agent model when no override is provided", async () => {
    writeWorkerAgent(dirs.cwd, "agent-default-model");
    writeCrewConfig(dirs.cwd, { worker: null });

    await spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
    }], dirs.cwd);

    const args = spawnMock.mock.calls[0][1] as string[];
    const modelFlagIndex = args.indexOf("--model");

    expect(modelFlagIndex).toBeGreaterThan(-1);
    expect(args[modelFlagIndex + 1]).toBe("agent-default-model");
  });

  it("spawnAgents splits provider/model into --provider and --model flags", async () => {
    writeWorkerAgent(dirs.cwd, "zai/glm-5");
    writeCrewConfig(dirs.cwd, { worker: null });

    await spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
    }], dirs.cwd);

    const args = spawnMock.mock.calls[0][1] as string[];
    const providerIdx = args.indexOf("--provider");
    const modelIdx = args.indexOf("--model");

    expect(providerIdx).toBeGreaterThan(-1);
    expect(args[providerIdx + 1]).toBe("zai");
    expect(modelIdx).toBeGreaterThan(-1);
    expect(args[modelIdx + 1]).toBe("glm-5");
  });

  it("spawnAgents treats bare .js tool entries as extension paths", async () => {
    writeWorkerAgent(dirs.cwd, undefined, ["read", "pi_messenger", "custom-tool.js"]);

    await spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
    }], dirs.cwd);

    const args = spawnMock.mock.calls[0][1] as string[];
    const toolsIdx = args.indexOf("--tools");
    const extensionIdx = args.indexOf("--extension");

    expect(toolsIdx).toBeGreaterThan(-1);
    expect(args[toolsIdx + 1]).toBe("read,pi_messenger");
    expect(extensionIdx).toBeGreaterThan(-1);
    expect(args[extensionIdx + 1]).toBe("custom-tool.js");
  });

  it("uses pi.cmd for worker subprocesses on Windows", async () => {
    const originalPlatform = Object.getOwnPropertyDescriptor(process, "platform");
    Object.defineProperty(process, "platform", { value: "win32" });
    try {
      writeWorkerAgent(dirs.cwd);

      await spawnAgents([{
        agent: "crew-worker",
        task: "Implement task",
        taskId: "task-1",
      }], dirs.cwd);

      expect(spawnMock.mock.calls[0][0]).toBe("pi.cmd");
    } finally {
      if (originalPlatform) Object.defineProperty(process, "platform", originalPlatform);
    }
  });

  describe("pushModelArgs", () => {
    it("splits provider/model into separate flags", () => {
      const args: string[] = [];
      pushModelArgs(args, "zai/glm-5");
      expect(args).toEqual(["--provider", "zai", "--model", "glm-5"]);
    });

    it("passes plain model as --model only", () => {
      const args: string[] = [];
      pushModelArgs(args, "claude-sonnet-4");
      expect(args).toEqual(["--model", "claude-sonnet-4"]);
    });

    it("splits on first slash only for openrouter-style IDs", () => {
      const args: string[] = [];
      pushModelArgs(args, "openrouter/anthropic/claude-3-5-sonnet");
      expect(args).toEqual(["--provider", "openrouter", "--model", "anthropic/claude-3-5-sonnet"]);
    });
  });
});

import * as fs from "node:fs";
import * as path from "node:path";
import { EventEmitter } from "node:events";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { createTempCrewDirs, type TempCrewDirs } from "../helpers/temp-dirs.ts";

const spawnMock = vi.hoisted(() => vi.fn());

vi.mock("node:child_process", () => ({
  spawn: spawnMock,
}));

type MockProcess = EventEmitter & {
  stdout: EventEmitter;
  stderr: EventEmitter;
  exitCode: number | null;
  killed: boolean;
  kill: ReturnType<typeof vi.fn>;
};

function createProcess(): MockProcess {
  const proc = new EventEmitter() as MockProcess;
  proc.stdout = new EventEmitter();
  proc.stderr = new EventEmitter();
  proc.exitCode = null;
  proc.killed = false;
  proc.kill = vi.fn(() => {
    proc.killed = true;
    proc.exitCode = 143;
    queueMicrotask(() => {
      proc.emit("exit", proc.exitCode);
      proc.emit("close", proc.exitCode);
    });
    return true;
  });
  return proc;
}

function writeWorkerAgent(cwd: string): void {
  const filePath = path.join(cwd, ".pi", "messenger", "crew", "agents", "crew-worker.md");
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `---
name: crew-worker
description: Test worker
crewRole: worker
---
You are a test worker.
`);
}

describe("crew agent event handling", () => {
  let dirs: TempCrewDirs;

  beforeEach(() => {
    dirs = createTempCrewDirs();
    writeWorkerAgent(dirs.cwd);
    spawnMock.mockReset();
  });

  it("compacts streaming message_update artifacts while preserving final output", async () => {
    const proc = createProcess();
    spawnMock.mockReturnValue(proc);
    const { spawnAgents } = await import("../../crew/agents.ts");

    const resultPromise = spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
    }], dirs.cwd);

    const repeated = "SNAPSHOT_CONTENT".repeat(100);
    proc.stdout.emit("data", `${JSON.stringify({
      type: "message_update",
      assistantMessageEvent: { type: "text_delta", delta: "ok", partial: { role: "assistant", content: [{ type: "text", text: repeated }] } },
      message: { role: "assistant", content: [{ type: "text", text: repeated }] },
    })}\n${JSON.stringify({
      type: "message_end",
      message: { role: "assistant", content: [{ type: "text", text: "FINAL" }] },
    })}\n`);
    proc.exitCode = 0;
    proc.emit("close", 0);

    const [result] = await resultPromise;

    expect(result.output).toBe("FINAL");
    const artifact = fs.readdirSync(path.join(dirs.crewDir, "artifacts")).find(file => file.endsWith(".jsonl"));
    expect(artifact).toBeTruthy();
    const jsonl = fs.readFileSync(path.join(dirs.crewDir, "artifacts", artifact!), "utf-8");
    expect(jsonl).not.toContain("SNAPSHOT_CONTENT");
    expect(jsonl).toContain("text_delta");
  });

  it("fails fast on terminal provider quota errors", async () => {
    const proc = createProcess();
    spawnMock.mockReturnValue(proc);
    const { spawnAgents } = await import("../../crew/agents.ts");

    const resultPromise = spawnAgents([{
      agent: "crew-worker",
      task: "Implement task",
      taskId: "task-1",
    }], dirs.cwd);

    proc.stdout.emit("data", `${JSON.stringify({
      type: "provider_error",
      error: {
        status: 400,
        type: "invalid_request_error",
        message: "Third-party apps now draw from your extra usage. Add more at claude.ai/settings/usage and keep going.",
      },
    })}\n`);

    const [result] = await resultPromise;

    expect(proc.kill).toHaveBeenCalledWith("SIGTERM");
    expect(result.exitCode).toBe(1);
    expect(result.error).toContain("Provider error 400");
  });
});

