import { randomUUID } from "node:crypto";
import { matchesKey, type TUI } from "@earendil-works/pi-tui";
import type { AgentMailMessage, Dirs, MessengerState } from "./lib.ts";
import { MAX_CHAT_HISTORY } from "./lib.ts";
import { sendMessageToAgent, getActiveAgents } from "./store.ts";
import { logFeedEvent } from "./feed.ts";
import * as crewStore from "./crew/store.ts";
import { executeTaskAction as runTaskAction } from "./crew/task-actions.ts";
import type { Task } from "./crew/types.ts";
import { getLiveWorkers } from "./crew/live-progress.ts";
import { hasActiveWorker } from "./crew/registry.ts";
import { cancelPlanningRun } from "./crew/state.ts";

interface ConfirmAction {
  type: "reset" | "cascade-reset" | "delete" | "cancel-planning";
  taskId: string;
  label: string;
}

export interface CrewViewState {
  scrollOffset: number;
  selectedTaskIndex: number;
  mode: "list" | "detail";
  detailScroll: number;
  detailAutoScroll: boolean;
  confirmAction: ConfirmAction | null;
  blockReasonInput: string;
  messageInput: string;
  inputMode: "normal" | "block-reason" | "message" | "revise-prompt";
  reviseScope: "single" | "tree";
  revisePromptInput: string;
  lastSeenEventTs: string | null;
  notification: { message: string; expiresAt: number } | null;
  notificationTimer: ReturnType<typeof setTimeout> | null;
  feedFocus: boolean;
  mentionCandidates: string[];
  mentionIndex: number;
}

export function createCrewViewState(): CrewViewState {
  return {
    scrollOffset: 0,
    selectedTaskIndex: 0,
    mode: "list",
    detailScroll: 0,
    detailAutoScroll: true,
    confirmAction: null,
    blockReasonInput: "",
    messageInput: "",
    inputMode: "normal",
    reviseScope: "single",
    revisePromptInput: "",
    lastSeenEventTs: null,
    notification: null,
    notificationTimer: null,
    feedFocus: false,
    mentionCandidates: [],
    mentionIndex: -1,
  };
}

function hasLiveWorker(cwd: string, taskId: string): boolean {
  return hasActiveWorker(cwd, taskId);
}

function isPrintable(data: string): boolean {
  return data.length > 0 && data.charCodeAt(0) >= 32;
}

function executeTaskAction(
  cwd: string,
  action: string,
  taskId: string,
  agentName: string,
  reason?: string,
): { success: boolean; message: string } {
  if (
    action !== "start" &&
    action !== "block" &&
    action !== "unblock" &&
    action !== "reset" &&
    action !== "cascade-reset" &&
    action !== "delete" &&
    action !== "stop"
  ) {
    return { success: false, message: `Unknown action: ${action}` };
  }

  const result = runTaskAction(cwd, action, taskId, agentName, reason, {
    isWorkerActive: id => hasLiveWorker(cwd, id),
  });
  return { success: result.success, message: result.message };
}

export function setNotification(viewState: CrewViewState, tui: TUI, success: boolean, message: string): void {
  if (viewState.notificationTimer) clearTimeout(viewState.notificationTimer);
  viewState.notification = { message: `${success ? "✓" : "✗"} ${message}`, expiresAt: Date.now() + 2000 };
  viewState.notificationTimer = setTimeout(() => {
    viewState.notificationTimer = null;
    tui.requestRender();
  }, 2000);
}

function addToChatHistory(state: MessengerState, recipient: string, message: AgentMailMessage): void {
  let history = state.chatHistory.get(recipient);
  if (!history) {
    history = [];
    state.chatHistory.set(recipient, history);
  }
  history.push(message);
  if (history.length > MAX_CHAT_HISTORY) history.shift();
}

function addToBroadcastHistory(state: MessengerState, text: string): void {
  const broadcastMsg: AgentMailMessage = {
    id: randomUUID(),
    from: state.agentName,
    to: "broadcast",
    text,
    timestamp: new Date().toISOString(),
    replyTo: null,
  };
  state.broadcastHistory.push(broadcastMsg);
  if (state.broadcastHistory.length > MAX_CHAT_HISTORY) {
    state.broadcastHistory.shift();
  }
}

function previewText(text: string): string {
  return text.length > 200 ? `${text.slice(0, 197)}...` : text;
}

export function handleConfirmInput(data: string, viewState: CrewViewState, cwd: string, agentName: string, tui: TUI): void {
  const action = viewState.confirmAction;
  if (!action) return;
  if (matchesKey(data, "y")) {
    if (action.type === "cancel-planning") {
      cancelPlanningRun(cwd);
      logFeedEvent(cwd, agentName, "plan.cancel");
      viewState.confirmAction = null;
      setNotification(viewState, tui, true, "Planning cancelled");
      tui.requestRender();
      return;
    }
    const result = executeTaskAction(cwd, action.type, action.taskId, agentName);
    if (action.type === "delete") {
      const tasks = crewStore.getTasks(cwd);
      if (tasks.length > 0) {
        viewState.selectedTaskIndex = Math.max(0, Math.min(viewState.selectedTaskIndex, tasks.length - 1));
      } else {
        viewState.selectedTaskIndex = 0;
        if (viewState.mode === "detail") viewState.mode = "list";
      }
    }
    viewState.confirmAction = null;
    setNotification(viewState, tui, result.success, result.message);
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "n") || matchesKey(data, "escape")) {
    viewState.confirmAction = null;
    tui.requestRender();
  }
}

export function handleBlockReasonInput(
  data: string,
  viewState: CrewViewState,
  cwd: string,
  task: Task | undefined,
  agentName: string,
  tui: TUI,
): void {
  if (matchesKey(data, "escape")) {
    viewState.inputMode = "normal";
    viewState.blockReasonInput = "";
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "enter")) {
    const reason = viewState.blockReasonInput.trim();
    if (!reason || !task) return;
    const result = executeTaskAction(cwd, "block", task.id, agentName, reason);
    viewState.inputMode = "normal";
    viewState.blockReasonInput = "";
    setNotification(viewState, tui, result.success, result.message);
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "backspace")) {
    if (viewState.blockReasonInput.length > 0) {
      viewState.blockReasonInput = viewState.blockReasonInput.slice(0, -1);
      tui.requestRender();
    }
    return;
  }
  if (isPrintable(data)) {
    viewState.blockReasonInput += data;
    tui.requestRender();
  }
}

export function handleRevisePromptInput(
  data: string,
  viewState: CrewViewState,
  cwd: string,
  task: Task | undefined,
  agentName: string,
  tui: TUI,
): void {
  if (matchesKey(data, "escape")) {
    viewState.inputMode = "normal";
    viewState.revisePromptInput = "";
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "enter")) {
    if (!task) return;
    if (task.status === "in_progress") {
      setNotification(viewState, tui, false, "Cannot revise in_progress task");
      viewState.inputMode = "normal";
      viewState.revisePromptInput = "";
      tui.requestRender();
      return;
    }

    const prompt = viewState.revisePromptInput.trim() || undefined;
    const scope = viewState.reviseScope;
    viewState.inputMode = "normal";
    viewState.revisePromptInput = "";

    const label = scope === "tree" ? `Revising ${task.id} + tree...` : `Revising ${task.id}...`;
    setNotification(viewState, tui, true, label);

    const vs = viewState;
    const t = tui;
    const fn = scope === "tree" ? "executeReviseTree" : "executeRevise";
    import("./crew/handlers/revise.ts")
      .then(m => m[fn](cwd, task.id, prompt, agentName))
      .then(result => {
        setNotification(vs, t, result.success, result.message);
      })
      .catch(err => {
        logFeedEvent(cwd, agentName, scope === "tree" ? "task.revise-tree" : "task.revise", task.id, `failed: ${err instanceof Error ? err.message : "unknown"}`);
      });
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "backspace")) {
    if (viewState.revisePromptInput.length > 0) {
      viewState.revisePromptInput = viewState.revisePromptInput.slice(0, -1);
      tui.requestRender();
    }
    return;
  }
  if (isPrintable(data)) {
    viewState.revisePromptInput += data;
    tui.requestRender();
  }
}

function resetMessageInput(viewState: CrewViewState): void {
  viewState.inputMode = "normal";
  viewState.messageInput = "";
  viewState.mentionCandidates = [];
  viewState.mentionIndex = -1;
}

function collectMentionCandidates(
  prefix: string,
  state: MessengerState,
  dirs: Dirs,
  cwd: string,
): string[] {
  const seen = new Set<string>();
  const names: string[] = [];

  for (const agent of getActiveAgents(state, dirs)) {
    if (agent.name === state.agentName) continue;
    if (!seen.has(agent.name)) {
      seen.add(agent.name);
      names.push(agent.name);
    }
  }

  for (const worker of getLiveWorkers(cwd).values()) {
    if (!seen.has(worker.name)) {
      seen.add(worker.name);
      names.push(worker.name);
    }
  }

  names.push("all");

  if (!prefix) return names;
  const lower = prefix.toLowerCase();
  return names.filter(n => n.toLowerCase().startsWith(lower));
}

function sendDirectMessage(
  state: MessengerState,
  dirs: Dirs,
  cwd: string,
  target: string,
  text: string,
  tui: TUI,
  viewState: CrewViewState,
): void {
  try {
    const msg = sendMessageToAgent(state, dirs, target, text);
    addToChatHistory(state, target, msg);
    logFeedEvent(cwd, state.agentName, "message", target, previewText(text));
    resetMessageInput(viewState);
    setNotification(viewState, tui, true, `Sent to ${target}`);
    tui.requestRender();
  } catch (err) {
    const msg = err instanceof Error ? err.message : "unknown error";
    setNotification(viewState, tui, false, `Failed to send to ${target}: ${msg}`);
    tui.requestRender();
  }
}

function sendBroadcastMessage(
  state: MessengerState,
  dirs: Dirs,
  cwd: string,
  text: string,
  tui: TUI,
  viewState: CrewViewState,
): void {
  const peers = getActiveAgents(state, dirs);
  if (peers.length === 0) {
    setNotification(viewState, tui, false, "No peers available for @all");
    tui.requestRender();
    return;
  }

  let sentCount = 0;
  for (const peer of peers) {
    try {
      sendMessageToAgent(state, dirs, peer.name, text);
      sentCount++;
    } catch {
      // Ignore per-recipient failures
    }
  }

  if (sentCount === 0) {
    setNotification(viewState, tui, false, "Broadcast failed");
    tui.requestRender();
    return;
  }

  addToBroadcastHistory(state, text);
  logFeedEvent(cwd, state.agentName, "message", undefined, previewText(text));
  resetMessageInput(viewState);
  setNotification(viewState, tui, true, `Broadcast to ${sentCount} peer${sentCount === 1 ? "" : "s"}`);
  tui.requestRender();
}

export function handleMessageInput(
  data: string,
  viewState: CrewViewState,
  state: MessengerState,
  dirs: Dirs,
  cwd: string,
  tui: TUI,
): void {
  if (matchesKey(data, "escape")) {
    resetMessageInput(viewState);
    tui.requestRender();
    return;
  }

  if (matchesKey(data, "tab") || matchesKey(data, "shift+tab")) {
    const input = viewState.messageInput;
    const cycling = viewState.mentionIndex >= 0 && viewState.mentionCandidates.length > 0;
    if (!input.startsWith("@") || (input.includes(" ") && !cycling)) return;

    const reverse = matchesKey(data, "shift+tab");

    if (!cycling) {
      const prefix = input.slice(1);
      viewState.mentionCandidates = collectMentionCandidates(prefix, state, dirs, cwd);
      if (viewState.mentionCandidates.length === 0) return;
      viewState.mentionIndex = 0;
    } else {
      const delta = reverse ? -1 : 1;
      viewState.mentionIndex = (viewState.mentionIndex + delta + viewState.mentionCandidates.length) % viewState.mentionCandidates.length;
    }

    viewState.messageInput = `@${viewState.mentionCandidates[viewState.mentionIndex]} `;
    tui.requestRender();
    return;
  }

  if (matchesKey(data, "enter")) {
    const raw = viewState.messageInput.trim();
    if (!raw) return;

    if (raw.startsWith("@all ")) {
      const text = raw.slice(5).trim();
      if (!text) return;
      sendBroadcastMessage(state, dirs, cwd, text, tui, viewState);
      return;
    }

    if (raw.startsWith("@")) {
      const firstSpace = raw.indexOf(" ");
      if (firstSpace <= 1) {
        setNotification(viewState, tui, false, "Use @name <message> or type to broadcast");
        tui.requestRender();
        return;
      }

      const target = raw.slice(1, firstSpace).trim();
      const text = raw.slice(firstSpace + 1).trim();
      if (!target || !text) {
        setNotification(viewState, tui, false, "Use @name <message> or type to broadcast");
        tui.requestRender();
        return;
      }

      sendDirectMessage(state, dirs, cwd, target, text, tui, viewState);
      return;
    }

    sendBroadcastMessage(state, dirs, cwd, raw, tui, viewState);
    return;
  }

  if (matchesKey(data, "backspace")) {
    if (viewState.messageInput.length > 0) {
      viewState.messageInput = viewState.messageInput.slice(0, -1);
      viewState.mentionCandidates = [];
      viewState.mentionIndex = -1;
      tui.requestRender();
    }
    return;
  }

  if (isPrintable(data)) {
    viewState.messageInput += data;
    viewState.mentionCandidates = [];
    viewState.mentionIndex = -1;
    tui.requestRender();
  }
}

export function handleCrewKeyBinding(
  data: string,
  task: Task,
  viewState: CrewViewState,
  cwd: string,
  agentName: string,
  tui: TUI,
): void {
  if (matchesKey(data, "r") && ["done", "blocked", "in_progress"].includes(task.status)) {
    viewState.confirmAction = { type: "reset", taskId: task.id, label: task.title };
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "shift+r") && ["done", "blocked", "in_progress"].includes(task.status)) {
    viewState.confirmAction = { type: "cascade-reset", taskId: task.id, label: task.title };
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "u") && task.status === "blocked") {
    const result = executeTaskAction(cwd, "unblock", task.id, agentName);
    setNotification(viewState, tui, result.success, result.message);
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "shift+s") && task.status !== "done" && !task.milestone) {
    setNotification(viewState, tui, true, `Split: pi_messenger({ action: "task.split", id: "${task.id}" })`);
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "b") && task.status === "in_progress") {
    viewState.inputMode = "block-reason";
    viewState.blockReasonInput = "";
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "q") && task.status === "in_progress") {
    const result = executeTaskAction(cwd, "stop", task.id, agentName);
    setNotification(viewState, tui, result.success, result.message);
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "x")) {
    if (task.status === "in_progress" && hasLiveWorker(cwd, task.id)) return;
    viewState.confirmAction = { type: "delete", taskId: task.id, label: task.title };
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "p") && task.status !== "in_progress" && !task.milestone) {
    viewState.inputMode = "revise-prompt";
    viewState.reviseScope = "single";
    viewState.revisePromptInput = "";
    tui.requestRender();
    return;
  }
  if (matchesKey(data, "shift+p") && task.status !== "in_progress" && !task.milestone) {
    viewState.inputMode = "revise-prompt";
    viewState.reviseScope = "tree";
    viewState.revisePromptInput = "";
    tui.requestRender();
    return;
  }
}

import { logFeedEvent } from "../feed.ts";
import * as store from "./store.ts";
import { loadCrewConfig } from "./utils/config.ts";
import { killWorkerByTask } from "./registry.ts";
import type { Task } from "./types.ts";

export type TaskAction = "start" | "block" | "unblock" | "reset" | "cascade-reset" | "delete" | "stop";

export interface TaskActionOptions {
  isWorkerActive?: (taskId: string) => boolean;
}

export interface TaskActionResult {
  success: boolean;
  message: string;
  error?: string;
  task?: Task;
  resetTasks?: Task[];
  unmetDependencies?: string[];
}

export function executeTaskAction(
  cwd: string,
  action: TaskAction,
  taskId: string,
  agentName: string,
  reason?: string,
  options?: TaskActionOptions,
): TaskActionResult {
  const task = store.getTask(cwd, taskId);
  if (!task) return { success: false, error: "not_found", message: `Task ${taskId} not found` };

  switch (action) {
    case "start": {
      if (task.milestone) {
        return { success: false, error: "milestone_not_startable", message: `Task ${taskId} is a milestone and cannot be started manually` };
      }
      if (task.status === "in_progress" && task.assigned_to === agentName) {
        return { success: true, message: `Already started ${taskId}`, task };
      }
      if (task.status !== "todo") {
        return { success: false, error: "invalid_status", message: `Task ${taskId} is ${task.status}, not todo` };
      }
      const config = loadCrewConfig(store.getCrewDir(cwd));
      if (config.dependencies !== "advisory") {
        const unmetDependencies = task.depends_on.filter(depId => store.getTask(cwd, depId)?.status !== "done");
        if (unmetDependencies.length > 0) {
          return {
            success: false,
            error: "unmet_dependencies",
            message: `Unmet dependencies: ${unmetDependencies.join(", ")}`,
            unmetDependencies,
          };
        }
      }
      const started = store.startTask(cwd, taskId, agentName);
      if (!started) return { success: false, error: "start_failed", message: `Failed to start ${taskId}` };
      logFeedEvent(cwd, agentName, "task.start", taskId, started.title);
      return { success: true, message: `Started ${taskId}`, task: started };
    }

    case "block": {
      if (task.status !== "in_progress") {
        return { success: false, error: "invalid_status", message: `Task ${taskId} must be in_progress to block` };
      }
      if (!reason) {
        return { success: false, error: "missing_reason", message: `Reason required to block ${taskId}` };
      }
      const blocked = store.blockTask(cwd, taskId, reason);
      if (!blocked) return { success: false, error: "block_failed", message: `Failed to block ${taskId}` };
      logFeedEvent(cwd, agentName, "task.block", taskId, reason);
      return { success: true, message: `Blocked ${taskId}`, task: blocked };
    }

    case "unblock": {
      if (task.status !== "blocked") {
        return { success: false, error: "invalid_status", message: `Task ${taskId} is ${task.status}, not blocked` };
      }
      const unblocked = store.unblockTask(cwd, taskId);
      if (!unblocked) return { success: false, error: "unblock_failed", message: `Failed to unblock ${taskId}` };
      logFeedEvent(cwd, agentName, "task.unblock", taskId, unblocked.title);
      return { success: true, message: `Unblocked ${taskId}`, task: unblocked };
    }

    case "reset": {
      if (options?.isWorkerActive?.(taskId)) {
        return { success: false, error: "active_worker", message: `Cannot reset ${taskId} while its worker is active` };
      }
      const resetTasks = store.resetTask(cwd, taskId, false);
      if (resetTasks.length === 0) return { success: false, error: "reset_failed", message: `Failed to reset ${taskId}` };
      logFeedEvent(cwd, agentName, "task.reset", taskId, task.title);
      return { success: true, message: `Reset ${taskId}`, resetTasks };
    }

    case "cascade-reset": {
      const subtree = [task, ...store.getTransitiveDependents(cwd, taskId)];
      const activeTask = subtree.find(t => options?.isWorkerActive?.(t.id));
      if (activeTask) {
        return { success: false, error: "active_worker", message: `Cannot reset ${activeTask.id} while its worker is active` };
      }
      const resetTasks = store.resetTask(cwd, taskId, true);
      if (resetTasks.length === 0) return { success: false, error: "reset_failed", message: `Failed to reset ${taskId}` };
      logFeedEvent(cwd, agentName, "task.reset", taskId, `cascade (${resetTasks.length} tasks)`);
      return { success: true, message: `Reset ${taskId} + ${Math.max(0, resetTasks.length - 1)} dependents`, resetTasks };
    }

    case "delete": {
      if (task.status === "in_progress" && options?.isWorkerActive?.(taskId)) {
        return { success: false, error: "active_worker", message: `Cannot delete ${taskId} while its worker is active` };
      }
      if (!store.deleteTask(cwd, taskId)) return { success: false, error: "delete_failed", message: `Failed to delete ${taskId}` };
      logFeedEvent(cwd, agentName, "task.delete", taskId, task.title);
      return { success: true, message: `Deleted ${taskId}` };
    }

    case "stop": {
      if (task.status !== "in_progress") {
        return { success: false, error: "invalid_status", message: `Task ${taskId} is ${task.status}, not in_progress` };
      }
      if (options?.isWorkerActive?.(taskId)) {
        killWorkerByTask(cwd, taskId);
        store.appendTaskProgress(cwd, taskId, agentName, "Worker stopped by user");
      } else {
        store.appendTaskProgress(cwd, taskId, agentName, "Task unassigned (no active worker)");
      }
      store.updateTask(cwd, taskId, { status: "todo", assigned_to: undefined });
      logFeedEvent(cwd, agentName, "task.reset", taskId, "stopped");
      return { success: true, message: `Stopped ${taskId}` };
    }
  }
}

import * as fs from "node:fs";
import * as path from "node:path";
import { homedir } from "node:os";

const CREW_AGENTS = [
  "crew-planner.md",
  "crew-plan-sync.md",
  "crew-worker.md",
  "crew-reviewer.md",
];

const DEPRECATED_AGENTS = [
  "crew-repo-scout.md",
  "crew-practice-scout.md",
  "crew-docs-scout.md",
  "crew-web-scout.md",
  "crew-github-scout.md",
  "crew-gap-analyst.md",
  "crew-interview-generator.md",
];

const DEFAULT_MIGRATION_MARKER = "legacy-crew-agent-cleanup-v1.json";

export interface InstallOptions {
  homeDir?: string;
  migrationMarker?: string;
}

function getTargetAgentsDir(homeDir: string): string {
  return path.join(homeDir, ".pi", "agent", "agents");
}

function getMigrationMarkerPath(homeDir: string, marker: string): string {
  return path.join(homeDir, ".pi", "agent", "messenger", "migrations", marker);
}

export function uninstallAgents(options: InstallOptions = {}): { removed: string[]; errors: string[] } {
  const homeDir = options.homeDir ?? homedir();
  const targetAgentsDir = getTargetAgentsDir(homeDir);
  const removed: string[] = [];
  const errors: string[] = [];

  for (const agent of [...CREW_AGENTS, ...DEPRECATED_AGENTS]) {
    const target = path.join(targetAgentsDir, agent);
    try {
      if (fs.existsSync(target)) {
        fs.unlinkSync(target);
        removed.push(agent);
      }
    } catch (err) {
      errors.push(`Failed to remove ${agent}: ${err}`);
    }
  }

  return { removed, errors };
}

export function runLegacyAgentCleanupMigration(options: InstallOptions = {}): {
  ran: boolean;
  removed: string[];
  errors: string[];
} {
  const homeDir = options.homeDir ?? homedir();
  const migrationMarker = options.migrationMarker ?? DEFAULT_MIGRATION_MARKER;
  const markerPath = getMigrationMarkerPath(homeDir, migrationMarker);

  if (fs.existsSync(markerPath)) {
    return { ran: false, removed: [], errors: [] };
  }

  const uninstallResult = uninstallAgents({ homeDir });

  try {
    fs.mkdirSync(path.dirname(markerPath), { recursive: true });
    fs.writeFileSync(markerPath, JSON.stringify({
      migratedAt: new Date().toISOString(),
      removed: uninstallResult.removed,
      errors: uninstallResult.errors,
    }, null, 2));
  } catch (err) {
    uninstallResult.errors.push(`Failed to persist migration marker: ${err}`);
  }

  return { ran: true, removed: uninstallResult.removed, errors: uninstallResult.errors };
}

/**
 * Crew - Agent Spawning
 * 
 * Spawns pi processes with progress tracking, truncation, and artifacts.
 */

import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { discoverCrewAgents, type CrewAgentConfig } from "./utils/discover.ts";
import { truncateOutput } from "./utils/truncate.ts";
import {
  createProgress,
  parseJsonlLine,
  updateProgress,
  getAssistantText,
  compactEventForArtifact,
  getTerminalProviderError,
  type PiEvent,
} from "./utils/progress.ts";
import {
  getArtifactPaths,
  ensureArtifactsDir,
  writeArtifact,
  writeMetadata,
  appendJsonl
} from "./utils/artifacts.ts";
import { loadCrewConfig, getTruncationForRole, type CrewConfig } from "./utils/config.ts";
import { removeLiveWorker, updateLiveWorker } from "./live-progress.ts";
import { autonomousState, waitForConcurrencyChange } from "./state.ts";
import { registerWorker, unregisterWorker, killAll } from "./registry.ts";
import type { AgentTask, AgentResult } from "./types.ts";
import { generateMemorableName } from "../lib.ts";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const EXTENSION_DIR = path.resolve(__dirname, "..");

export interface SpawnOptions {
  onProgress?: (results: AgentResult[]) => void;
  crewDir?: string;
  signal?: AbortSignal;
  messengerDirs?: { registry: string; inbox: string };
}

export function shutdownAllWorkers(): void {
  killAll();
}

export function resolveModel(
  taskModel?: string,
  paramModel?: string,
  roleModel?: string,
  configModel?: string,
  sessionModel?: string,
  agentModel?: string,
): string | undefined {
  return taskModel ?? paramModel ?? roleModel ?? configModel ?? sessionModel ?? agentModel;
}

export function getPiCommand(): string {
  return process.platform === "win32" ? "pi.cmd" : "pi";
}

export function pushModelArgs(args: string[], model: string): void {
  const slashIdx = model.indexOf("/");
  if (slashIdx !== -1) {
    args.push("--provider", model.substring(0, slashIdx), "--model", model.substring(slashIdx + 1));
  } else {
    args.push("--model", model);
  }
}

const THINKING_LEVELS = new Set(["off", "minimal", "low", "medium", "high", "xhigh"]);

export function resolveThinking(
  configThinking?: string,
  agentThinking?: string,
): string | undefined {
  const resolved = configThinking ?? agentThinking;
  if (!resolved || resolved === "off") return undefined;
  return resolved;
}

export function modelHasThinkingSuffix(model: string | undefined): boolean {
  if (!model) return false;
  const colonIdx = model.lastIndexOf(":");
  if (colonIdx === -1) return false;
  return THINKING_LEVELS.has(model.substring(colonIdx + 1));
}

export function raceTimeout(promise: Promise<void>, ms: number): Promise<boolean> {
  return new Promise<boolean>(resolve => {
    const timer = setTimeout(() => resolve(false), ms);
    promise.then(
      () => {
        clearTimeout(timer);
        resolve(true);
      },
      () => {
        clearTimeout(timer);
        resolve(false);
      },
    );
  });
}

function discoverWorkerName(
  pid: number | undefined,
  registryDir: string | undefined
): string | null {
  if (!pid || !registryDir || !fs.existsSync(registryDir)) return null;
  try {
    for (const file of fs.readdirSync(registryDir)) {
      if (!file.endsWith(".json")) continue;
      const reg = JSON.parse(fs.readFileSync(path.join(registryDir, file), "utf-8"));
      if (reg.pid === pid) return reg.name;
    }
  } catch {}
  return null;
}

const SHUTDOWN_MESSAGE = `⚠️ SHUTDOWN REQUESTED: Please wrap up your current work.
1. Release any file reservations
2. If the task is not complete, leave it as in_progress (do NOT mark done)
3. Do NOT commit anything
4. Exit`;

/**
 * Spawn multiple agents in parallel with concurrency limit.
 */
export async function spawnAgents(
  tasks: AgentTask[],
  cwd: string,
  options: SpawnOptions = {}
): Promise<AgentResult[]> {
  const crewDir = options.crewDir ?? path.join(cwd, ".pi", "messenger", "crew");
  const config = loadCrewConfig(crewDir);
  const agents = discoverCrewAgents(cwd);
  const runId = randomUUID().slice(0, 8);

  // Setup artifacts directory if enabled
  const artifactsDir = path.join(crewDir, "artifacts");
  if (config.artifacts.enabled) {
    ensureArtifactsDir(artifactsDir, config.artifacts.cleanupDays);
  }

  const results: AgentResult[] = [];
  const queue = tasks.map((task, index) => ({ task, index }));
  const running: Promise<void>[] = [];

  while (queue.length > 0 || running.length > 0) {
    if (options.signal?.aborted && running.length === 0) break;

    while (running.length < autonomousState.concurrency && queue.length > 0) {
      if (options.signal?.aborted) break;
      const { task, index } = queue.shift()!;
      const promise = runAgent(task, index, cwd, agents, config, runId, artifactsDir, options)
        .then(result => {
          results.push(result);
          running.splice(running.indexOf(promise), 1);
          options.onProgress?.(results);
        });
      running.push(promise);
    }
    if (running.length > 0) {
      await Promise.race([...running, waitForConcurrencyChange()]);
      if (options.signal?.aborted) continue;
    }
  }

  return results;
}

async function runAgent(
  task: AgentTask,
  index: number,
  cwd: string,
  agents: CrewAgentConfig[],
  config: CrewConfig,
  runId: string,
  artifactsDir: string,
  options: SpawnOptions
): Promise<AgentResult> {
  const agentConfig = agents.find(a => a.name === task.agent);
  const progress = createProgress(task.agent);
  const startTime = Date.now();
  const workerName = generateMemorableName();

  const role = agentConfig?.crewRole ?? "worker";
  const maxOutput = task.maxOutput
    ?? agentConfig?.maxOutput
    ?? getTruncationForRole(config, role);

  let artifactPaths = config.artifacts.enabled
    ? getArtifactPaths(artifactsDir, runId, task.agent, index)
    : undefined;

  if (artifactPaths) {
    try {
      writeArtifact(artifactPaths.inputPath, `# Task for ${task.agent}\n\n${task.task}`);
    } catch {
      artifactPaths = undefined;
    }
  }

  return new Promise((resolve) => {
    // Build args for pi command
    const args = ["--mode", "json", "--no-session", "-p"];
    const model = task.modelOverride ?? config.models?.[role] ?? agentConfig?.model;
    if (model) pushModelArgs(args, model);

    const thinking = resolveThinking(
      config.thinking?.[role],
      agentConfig?.thinking,
    );
    if (thinking && !modelHasThinkingSuffix(model)) {
      args.push("--thinking", thinking);
    }

    if (agentConfig?.tools?.length) {
      const builtinTools: string[] = [];
      const extensionPaths: string[] = [];
      for (const tool of agentConfig.tools) {
        if (tool.includes("/") || tool.endsWith(".ts") || tool.endsWith(".js")) {
          extensionPaths.push(tool);
        } else {
          builtinTools.push(tool);
        }
      }

      if (builtinTools.length > 0) {
        args.push("--tools", builtinTools.join(","));
      }
      for (const extensionPath of extensionPaths) {
        args.push("--extension", extensionPath);
      }
    }

    // Pass extension so workers can use pi_messenger
    args.push("--extension", EXTENSION_DIR);

    let promptTmpDir: string | null = null;
    if (agentConfig?.systemPrompt) {
      promptTmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-messenger-agent-"));
      const promptPath = path.join(promptTmpDir, `${task.agent.replace(/[^\w.-]/g, "_")}.md`);
      fs.writeFileSync(promptPath, agentConfig.systemPrompt, { mode: 0o600 });
      args.push("--append-system-prompt", promptPath);
    }

    args.push(task.task);

    const envOverrides = config.work.env ?? {};
    const workerFlag = role === "worker"
      ? { PI_CREW_WORKER: "1", PI_AGENT_NAME: workerName }
      : {};
    const env = Object.keys(envOverrides).length > 0 || role === "worker"
      ? { ...process.env, ...envOverrides, ...workerFlag }
      : undefined;

    const proc = spawn(getPiCommand(), args, {
      cwd,
      stdio: ["ignore", "pipe", "pipe"],
      ...(env ? { env } : {}),
    });
    if (task.taskId) {
      registerWorker({ type: "worker", proc, name: workerName, cwd, taskId: task.taskId });
    }
    let gracefulShutdownRequested = false;
    let discoveredWorkerName: string | null = null;

    let jsonlBuffer = "";
    let fullOutput = "";
    let terminalProviderError: string | null = null;

    proc.stdout?.on("data", (data) => {
      try {
        jsonlBuffer += data.toString();
        const lines = jsonlBuffer.split("\n");
        jsonlBuffer = lines.pop() ?? "";

        for (const line of lines) {
          const event = parseJsonlLine(line);
          if (event) {
            updateProgress(progress, event, startTime);
            const assistantText = getAssistantText(event);
            if (assistantText) fullOutput = assistantText;
            if (artifactPaths) {
              try { appendJsonl(artifactPaths.jsonlPath, JSON.stringify(compactEventForArtifact(event))); }
              catch { artifactPaths = undefined; }
            }
            const providerError = getTerminalProviderError(event);
            if (providerError && !terminalProviderError) {
              terminalProviderError = providerError;
              progress.error = providerError;
              proc.kill("SIGTERM");
            }
            if (task.taskId) {
              updateLiveWorker(cwd, task.taskId, {
                taskId: task.taskId,
                agent: task.agent,
                name: workerName,
                progress: {
                  ...progress,
                  recentTools: progress.recentTools.map(tool => ({ ...tool })),
                },
                startedAt: startTime,
              });
            }
          }
        }
      } catch {}
    });

    let stderr = "";
    proc.stderr?.on("data", (data) => { stderr += data.toString(); });

    proc.on("close", (code) => {
      if (task.taskId) {
        removeLiveWorker(cwd, task.taskId);
        unregisterWorker(cwd, task.taskId);
      }
      const exitCode = terminalProviderError ? 1 : code ?? 1;
      progress.status = exitCode === 0 ? "completed" : "failed";
      progress.durationMs = Date.now() - startTime;
      if (terminalProviderError) progress.error = terminalProviderError;
      else if (stderr && exitCode !== 0) progress.error = stderr;

      const truncation = truncateOutput(fullOutput, maxOutput, artifactPaths?.outputPath);

      if (artifactPaths) {
        try {
          writeArtifact(artifactPaths.outputPath, fullOutput);
          writeMetadata(artifactPaths.metadataPath, {
            runId,
            agent: task.agent,
            index,
            exitCode,
            durationMs: progress.durationMs,
            tokens: progress.tokens,
            truncated: truncation.truncated,
            error: progress.error,
          });
        } catch {}
      }

      if (promptTmpDir) {
        try { fs.rmSync(promptTmpDir, { recursive: true, force: true }); } catch {}
      }

      resolve({
        agent: task.agent,
        exitCode,
        output: truncation.text,
        truncated: truncation.truncated,
        progress,
        config: agentConfig,
        taskId: task.taskId,
        wasGracefullyShutdown: gracefulShutdownRequested,
        error: progress.error,
        artifactPaths: artifactPaths ? {
          input: artifactPaths.inputPath,
          output: artifactPaths.outputPath,
          jsonl: artifactPaths.jsonlPath,
          metadata: artifactPaths.metadataPath,
        } : undefined,
      });

      if (gracefulShutdownRequested && discoveredWorkerName && options.messengerDirs?.registry) {
        try {
          fs.unlinkSync(path.join(options.messengerDirs.registry, `${discoveredWorkerName}.json`));
        } catch {}
      }
    });

    // Handle abort signal
    if (options.signal) {
      const gracefulShutdown = async () => {
        gracefulShutdownRequested = true;

        let messageSent = false;
        discoveredWorkerName = discoverWorkerName(proc.pid, options.messengerDirs?.registry);
        if (discoveredWorkerName && options.messengerDirs) {
          try {
            const inboxDir = path.join(options.messengerDirs.inbox, discoveredWorkerName);
            if (fs.existsSync(inboxDir)) {
              const msgFile = path.join(inboxDir, `${Date.now()}-shutdown.json`);
              fs.writeFileSync(msgFile, JSON.stringify({
                id: randomUUID(),
                from: "crew-orchestrator",
                to: discoveredWorkerName,
                text: SHUTDOWN_MESSAGE,
                timestamp: new Date().toISOString(),
                replyTo: null,
              }));
              messageSent = true;
            }
          } catch {}
        }

        if (messageSent) {
          const graceMs = config.work.shutdownGracePeriodMs ?? 30000;
          const exitPromise = new Promise<void>(r => proc.once("exit", () => r()));
          const exited = await raceTimeout(exitPromise, graceMs);
          if (exited) return;
        }

        if (!proc.killed && proc.exitCode === null) {
          proc.kill("SIGTERM");
          const termPromise = new Promise<void>(r => proc.once("exit", () => r()));
          const killed = await raceTimeout(termPromise, 5000);
          if (killed) return;
        } else {
          return;
        }

        if (proc.exitCode === null) {
          proc.kill("SIGKILL");
        }
      };
      if (options.signal.aborted) {
        gracefulShutdown().catch(() => {});
      } else {
        options.signal.addEventListener("abort", () => {
          gracefulShutdown().catch(() => {});
        }, { once: true });
      }
    }
  });
}

import * as fs from "node:fs";
import * as path from "node:path";
import { homedir } from "node:os";
import type { TeamRoleDefinition } from "./types.ts";
import { canonicalPackagedTeamRole, isValidTeamName } from "../utils/team-roles.ts";

export interface DiscoverSubagentRoleOptions {
  homeDir?: string;
}

function listMarkdownFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...listMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      out.push(full);
    }
  }
  return out.sort();
}

function splitList(value: string): string[] {
  const trimmed = value.trim();
  if (!trimmed) return [];
  if (trimmed.startsWith("[") && trimmed.endsWith("]")) {
    return trimmed.slice(1, -1).split(",").map(v => v.trim().replace(/^['\"]|['\"]$/g, "")).filter(Boolean);
  }
  return trimmed.split(",").map(v => v.trim()).filter(Boolean);
}

function parseFrontmatter(content: string): { data: Record<string, string>; body: string } {
  const normalized = content.replace(/\r\n/g, "\n");
  if (!normalized.startsWith("---\n")) return { data: {}, body: normalized };
  const end = normalized.indexOf("\n---", 4);
  if (end === -1) return { data: {}, body: content };
  const raw = normalized.slice(4, end);
  const data: Record<string, string> = {};
  for (const line of raw.split("\n")) {
    const idx = line.indexOf(":");
    if (idx <= 0) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim().replace(/^['\"]|['\"]$/g, "");
    if (key) data[key] = value;
  }
  const bodyStart = normalized.indexOf("\n", end + 4);
  return { data, body: bodyStart === -1 ? "" : normalized.slice(bodyStart + 1).trim() };
}

function readRoleFile(filePath: string, sourceLabel: string): TeamRoleDefinition | null {
  const content = fs.readFileSync(filePath, "utf-8");
  const { data, body } = parseFrontmatter(content);
  const rawName = data.name || path.basename(filePath, ".md");
  if (!isValidTeamName(rawName)) return null;
  const name = canonicalPackagedTeamRole(rawName) ?? rawName;

  return {
    name,
    ...(data.description ? { description: data.description } : {}),
    ...(data.model ? { model: data.model } : {}),
    ...(data.thinking ? { thinking: data.thinking } : {}),
    ...(data.skills ? { skills: splitList(data.skills) } : {}),
    ...(body ? { prompt: body.slice(0, 4000) } : {}),
    promptSource: `${sourceLabel}:${name}`,
  };
}

export function discoverSubagentRoles(cwd: string, options?: DiscoverSubagentRoleOptions): Record<string, TeamRoleDefinition> {
  const home = options?.homeDir ?? homedir();
  const sources = [
    { dir: path.join(home, ".pi", "agent", "extensions", "subagent", "agents"), label: "subagent:builtin" },
    { dir: path.join(home, ".pi", "agent", "agents"), label: "subagent:user" },
    { dir: path.join(cwd, ".pi", "agents"), label: "subagent:project" },
    { dir: path.join(cwd, ".agents"), label: "subagent:legacy-project" },
  ];

  const roles: Record<string, TeamRoleDefinition> = {};
  for (const source of sources) {
    for (const file of listMarkdownFiles(source.dir)) {
      const role = readRoleFile(file, source.label);
      if (role) roles[role.name] = { ...roles[role.name], ...role };
    }
  }
  return roles;
}

